import{_t as e,it as t,n,rt as r}from"./chunks/framework.BhEEDjPG.js";var i=JSON.parse(`{"title":"ADR 0001 — Domains and routing: compose within, delegate across","description":"","frontmatter":{},"headers":[],"relativePath":"reference/adr/0001-domains-and-routing.md","filePath":"reference/adr/0001-domains-and-routing.md"}`),a={name:`reference/adr/0001-domains-and-routing.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0001-—-domains-and-routing-compose-within-delegate-across" tabindex="-1">ADR 0001 — Domains and routing: compose within, delegate across <a class="header-anchor" href="#adr-0001-—-domains-and-routing-compose-within-delegate-across" aria-label="Permalink to “ADR 0001 — Domains and routing: compose within, delegate across”">​</a></h1><ul><li><strong>Status:</strong> Accepted</li><li><strong>Date:</strong> 2026-08-09 (origin), restated for Marg 2026-10-13</li><li><strong>Deciders:</strong> the first vertical&#39;s owner. Drafted with Claude Code.</li></ul><h2 id="_1-context" tabindex="-1">1. Context <a class="header-anchor" href="#_1-context" aria-label="Permalink to “1. Context”">​</a></h2><p>A single agent that did one job well (a system prompt that concatenated every skill, one MCP server with 13 tools) was to become a super agent with sibling capabilities (tasks, leads, matching). The question: how do these share one user-facing agent without the prompt and the tool list growing unbounded, and what package shape does each capability take?</p><h2 id="_2-decision-drivers" tabindex="-1">2. Decision drivers <a class="header-anchor" href="#_2-decision-drivers" aria-label="Permalink to “2. Decision drivers”">​</a></h2><ol><li>Context budget and tool-selection accuracy (more tools + skills in one prompt = worse choices, higher cost).</li><li>Guardrail isolation (one domain&#39;s confirm gate must not dilute in another&#39;s turns).</li><li>Per-domain evals as the regression gate.</li><li>Independent iteration and deploy.</li><li>Cross-domain flows must remain possible.</li><li>Cost controls and multi-tenancy are downstream — the shape must not fight them.</li></ol><h2 id="_3-options" tabindex="-1">3. Options <a class="header-anchor" href="#_3-options" aria-label="Permalink to “3. Options”">​</a></h2><ul><li><strong>A. Monolithic composition</strong> — one context with every domain&#39;s skills and tools. Simplest; no routing; cross-domain free. Does not scale past ~2 domains: tool accuracy degrades, every turn pays for every domain, guardrails blur, evals cannot isolate.</li><li><strong>B. Delegation</strong> — a thin router picks ONE domain per turn; each domain agent runs in its own context. Bounded context, isolated guardrails and evals, independent deploy. Costs a routing hop and explicit orchestration.</li><li><strong>C. Hybrid (chosen)</strong> — B across domains, A within: multiple skills per domain stay fine (orchestrator + deltas + shared behaviour); multiple domains in one context, never.</li></ul><h2 id="_4-decision" tabindex="-1">4. Decision <a class="header-anchor" href="#_4-decision" aria-label="Permalink to “4. Decision”">​</a></h2><p>Adopt C. The super agent is a router, not a doer: domain cards from the manifests, one domain per turn, sticky (stay until intent clearly shifts; never re-route mid-journey or after completion), fallback chain matched → active → first — routing never throws, a misroute degrades to a clarifying question, never a wrong write. Single domain ⇒ no classification. Cross-domain flows are sequenced by the super agent; domains stay unaware of each other; a domain that needs another&#39;s data gets a shared READ-only tool, never a write.</p><p><strong>One line:</strong> <em>within a domain, compose skills; across domains, delegate through the super agent.</em></p><h2 id="_5-the-convention" tabindex="-1">5. The convention <a class="header-anchor" href="#_5-the-convention" aria-label="Permalink to “5. The convention”">​</a></h2><p>A domain is a self-contained folder: <code>domain.json</code> (name, title, description = the router card, route hints, mcp, skills, shared skills, types, steps, evals), <code>skills/</code>, <code>mcp/</code>, <code>schema/</code>, <code>steps/</code>, <code>mock/</code>, <code>probe/</code>, <code>evals/</code>. Discovery globs the manifests at boot; a broken one is skipped, never fatal. Shared skills (behaviour, visual protocol) are injected into every domain agent.</p><h2 id="_6-consequences" tabindex="-1">6. Consequences <a class="header-anchor" href="#_6-consequences" aria-label="Permalink to “6. Consequences”">​</a></h2><ul><li>Context per turn stays the size of one domain regardless of how many exist.</li><li>The routing hop is a typed decision (ADR-0005) — keywords free, a decision model cheap, the LLM last.</li><li>Agent-as-tool (one domain calling another) is deliberately deferred.</li></ul><hr><p><small>Source: <a href="https://github.com/marg-adk/marg/blob/main/docs/adr/0001-domains-and-routing.md">docs/adr/0001-domains-and-routing.md</a> — edit it there; the site mirrors the repository.</small></p>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};